import{_ as t,o as e,c as o,ah as s}from"./chunks/framework.BdHuibk5.js";const h=JSON.parse('{"title":"The love story","description":"很久很久以前，一只香菇爱上了一只蘑菇，却在失落与沉默之间，等来了愿意陪他一起撑伞的鸡腿菇。","frontmatter":{"title":"The love story","date":"2010-12-04 23:09","category":"prose","tags":["爱情","故事"],"slug":"the-love-story-2010","layout":"blog-post","description":"很久很久以前，一只香菇爱上了一只蘑菇，却在失落与沉默之间，等来了愿意陪他一起撑伞的鸡腿菇。"},"headers":[],"relativePath":"blog/the-love-story-2010.md","filePath":"blog/posts/prose/the-love-story-2010.md","lastUpdated":1789447662000}'),r={name:"blog/the-love-story-2010.md"};function a(l,p,_,n,c,d){return e(),o("div",null,[...p[0]||(p[0]=[s("<p>很久很久很久以前，有一只香菇，他爱上了一只蘑菇，但蘑菇已经有了金针菇做男朋友。香菇看看自己，又黑又丑，再看看金针菇又帅又白又苗条，香菇觉得自己比不了金针菇配不上蘑菇，就偷偷地对蘑菇好，但从不让蘑菇知道那是爱，就好满足了。</p><p>有一天，蘑菇告诉香菇，她要和金针菇结婚了，香菇傻笑着祝福她，心却哭了。香菇觉得有比自己好的菇会陪她走完今后的路，自己的存在也没有意义了。就走向了超市的货柜……</p><p>香菇静静等待被采购的那一天。</p><p>“你的肤色好健康啊！”旁边传来了一个声音。</p><p>香蘑转过头，是一只鸡腿菇。</p><p>“……我家门口只有卖黑雨伞的……”</p><p>鸡腿菇笑了。香菇也笑了。两只菇就这么笑着聊着一天又一天……</p><p>“香菇哥哥，我喜欢你，你喜欢我吗”。</p><p>香菇没有回答。香菇想起了蘑菇。香菇没有忘记蘑菇。这一沉默，两个菇就再也没有了对话。</p><p>一只手伸向了他们。香菇迅猛挡在了鸡腿菇的前面，他被扔进了手推车。</p><p>他闭上了双眼。他终于完成了他的心愿，他被采购了，要被吃掉了，一切都结束了。他努力地回忆着他的一生、他的爱情，可突然他奇怪了，那个他连命都可以不要的爱情影象不在了，出现的却是……</p><p>“香菇哥哥，我喜欢你，我们永远在一起”</p><p>什么声音？这也是梦吗？感觉不像呢……睁开眼，看到了他的鸡腿菇。</p><p>“你怎么在这里”</p><p>“我跟你去买把黑雨伞，这样才配你啊”</p><p>香菇哭了。这次虽然在哭，但心里是甜的。</p><p>在下锅前，香菇对鸡腿菇说了最后一句话：“我也喜欢你”</p><p>我是一只蘑菇。又黑又丑。不过我可以当一把伞，就算只能为你撑出一片荫庇或挡住即刻的雨。</p>",18)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
